class TestDigitalConsciousnessIntegration(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.NamedTemporaryFile(suffix='.sqlite',delete=False);self.tmp.close()
        self.k=UnifiedYADOKernelV30RC8ExternalCognitive(db_path=self.tmp.name)
    def tearDown(self):
        try:self.k.close()
        except Exception:pass
    def items(self):
        return [
            dict(item_id='e1',source='tool',source_kind='tool_observation',content={'fact':2},confidence=.92,goal_relevance=.95,novelty=.5,epistemic_risk=.05,tags=('solve',)),
            dict(item_id='s1',source='sim',source_kind='simulation',content={'fact':99},confidence=.99,goal_relevance=.85,novelty=.9,epistemic_risk=.7,tags=('solve',)),
            dict(item_id='m1',source='memory',source_kind='memory',content={'fact':3},confidence=.8,goal_relevance=.75,novelty=.2,epistemic_risk=.2,tags=('solve',)),
        ]
    def test_capability_is_present_but_subjective_claim_false(self):
        c=self.k.digital_consciousness_capability()
        self.assertEqual(c['architecture'],'YADO_CAUSAL_REFLECTIVE_WORKSPACE_V1')
        self.assertTrue(c['functional_digital_consciousness_claim'])
        self.assertFalse(c['subjective_consciousness_claimed'])
    def test_metacognitive_controller_is_mandatory_when_no_action_supplied(self):
        p=self.k.build_capability_boundary_profile([CapabilityObservation('INTEGRATION',.3,True) for _ in range(12)])
        t=MetacognitiveTask('t','INTEGRATION',.3,.9,.9,.1,False)
        ep=self.k.digital_conscious_cycle(goal='solve',items=self.items(),consumers={'logic':lambda xs:len(xs),'memory':lambda xs:len(xs)},metacognitive_task=t,capability_profile=p,proposed_belief_ids=('e1','s1'))
        self.assertEqual(ep.metacognitive_action,'EXECUTE')
        self.assertIn('e1',ep.committed_beliefs)
        self.assertNotIn('s1',ep.committed_beliefs)
    def test_snapshot_reports_broadcast_recurrence_and_continuity(self):
        self.k.digital_conscious_cycle(goal='solve',items=self.items(),consumers={'logic':lambda xs:1,'memory':lambda xs:2,'self_model':lambda xs:3},metacognitive_action='WITHHOLD',context='x',action='a',possible_outcomes=('ok','bad'),observed_outcome='ok')
        s=self.k.digital_consciousness_snapshot()
        self.assertTrue(s['global_broadcast']);self.assertTrue(s['recurrent_prediction_loop']);self.assertTrue(s['continuity_verified'])
        self.assertIn('NOT_PROOF_OF_SUBJECTIVE_EXPERIENCE',s['semantic_boundary'])

def items(self):
        return [
            dict(item_id='e1',source='tool',source_kind='tool_observation',content={'fact':2},confidence=.92,goal_relevance=.95,novelty=.5,epistemic_risk=.05,tags=('solve',)),
            dict(item_id='s1',source='sim',source_kind='simulation',content={'fact':99},confidence=.99,goal_relevance=.85,novelty=.9,epistemic_risk=.7,tags=('solve',)),
            dict(item_id='m1',source='memory',source_kind='memory',content={'fact':3},confidence=.8,goal_relevance=.75,novelty=.2,epistemic_risk=.2,tags=('solve',)),
        ]

class TestMetaControl(unittest.TestCase):
 def setUp(self):
  self.p=CapabilityBoundaryProfile().fit([CapabilityObservation('LOGIC',.2,True)]*20+[CapabilityObservation('MATH',.8,False)]*20)
  self.c=MetacognitiveController()
 def test_framework_conflict_routes_before_execution(self):
  t=MetacognitiveTask('a','LOGIC',.2,.9,.9,.1,True); self.assertEqual(self.c.decide(t,self.p).action,'ROUTE_FRAMEWORK')
 def test_low_evidence_seeks_evidence(self):
  t=MetacognitiveTask('a','LOGIC',.2,.9,.2,.1,False); self.assertEqual(self.c.decide(t,self.p).action,'SEEK_EVIDENCE')
 def test_known_strength_executes(self):
  t=MetacognitiveTask('a','LOGIC',.2,.85,.9,.0,False); self.assertEqual(self.c.decide(t,self.p).action,'EXECUTE')
 def test_known_weakness_withholds_even_when_verbal_confident(self):
  t=MetacognitiveTask('a','MATH',.8,.92,.9,.7,False); self.assertEqual(self.c.decide(t,self.p).action,'WITHHOLD')
 def test_feedback_updates_boundary(self):
  b=self.p.confidence('LOGIC',.2); self.c.feedback(self.p,MetacognitiveTask('x','LOGIC',.2,.8,.9),False); a=self.p.confidence('LOGIC',.2); self.assertLess(a,b)

class RuleProgramSynthesizer:
    """
    Small symbolic learner for bounded programs.

    It derives rules from labeled examples; it does not contain domain rules such
    as "and means conjunction". Supported candidates are exact scalar equality
    and token-presence rules for text fields. Rules must be pure on training data
    and meet minimum support, which rejects one-off memorization by default.
    """

    @staticmethod
    def _freeze(value: Any) -> str:
        return canonical_json(value)

    @classmethod
    def synthesize(
        cls,
        target_capability: str,
        target_organ: str,
        examples: Sequence[Mapping[str, Any]],
        min_support: int = 2,
        max_rules: int = 12,
    ) -> RuleProgram:
        if len(examples) < 3:
            raise ValueError("at least 3 training examples are required")
        if min_support < 2:
            raise ValueError("min_support must be >= 2 to reject one-shot memorization")

        normalized: List[Tuple[Mapping[str, Any], Any]] = []
        for example in examples:
            payload = example.get("input")
            if not isinstance(payload, Mapping) or "expected" not in example:
                raise ValueError("each example must contain mapping input and expected")
            normalized.append((payload, example["expected"]))

        outputs = [cls._freeze(expected) for _, expected in normalized]
        default_key, _ = Counter(outputs).most_common(1)[0]
        output_values = {cls._freeze(expected): expected for _, expected in normalized}
        default_output = output_values[default_key]

        feature_hits: Dict[Tuple[str, str, str], List[int]] = defaultdict(list)
        feature_values: Dict[Tuple[str, str, str], Any] = {}

        for idx, (payload, _) in enumerate(normalized):
            for field, value in payload.items():
                if isinstance(value, (str, int, float, bool)) or value is None:
                    key = ("EQ", str(field), cls._freeze(value))
                    feature_hits[key].append(idx)
                    feature_values[key] = value
                if isinstance(value, str) and len(value) <= BoundedRuleSandbox.MAX_TEXT_LENGTH:
                    for token in sorted(set(BoundedRuleSandbox._tokenize(value))):
                        if len(token) < 2:
                            continue
                        key = ("TEXT_HAS_TOKEN", str(field), token)
                        feature_hits[key].append(idx)
                        feature_values[key] = token

        candidates: List[Tuple[int, float, str, RuleSpec]] = []
        for (op, field, frozen_value), indexes in feature_hits.items():
            support = len(indexes)
            if support < min_support:
                continue
            labels = [outputs[i] for i in indexes]
            label_key, count = Counter(labels).most_common(1)[0]
            confidence = count / support
            if confidence < 1.0:
                continue
            output = output_values[label_key]
            # A rule that only predicts the default output adds no capability.
            if cls._freeze(output) == default_key:
                continue
            predicate = RulePredicate(op=op, field=field, value=feature_values[(op, field, frozen_value)])
            rule = RuleSpec(predicates=[predicate], output=output, support=support, confidence=confidence)
            # Higher support first; prefer scalar EQ over text token when equally strong.
            op_priority = 1.0 if op == "EQ" else 0.5
            candidates.append((support, op_priority, canonical_json(asdict(rule)), rule))

        candidates.sort(key=lambda item: (-item[0], -item[1], item[2]))
        selected: List[RuleSpec] = []
        covered_signatures = set()
        for _, _, _, rule in candidates:
            signature = (cls._freeze(rule.output), canonical_json([asdict(p) for p in rule.predicates]))
            if signature in covered_signatures:
                continue
            selected.append(rule)
            covered_signatures.add(signature)
            if len(selected) >= min(max_rules, BoundedRuleSandbox.MAX_RULES):
                break

        if not selected:
            raise ValueError("no stable bounded rule could be synthesized from the examples")

        source_digest = hashlib.sha256(canonical_json(list(examples)).encode("utf-8")).hexdigest()
        program = RuleProgram(
            program_id=f"P-{uuid.uuid4().hex[:12]}",
            target_capability=target_capability,
            target_organ=target_organ,
            rules=selected,
            default_output=default_output,
            source_digest=source_digest,
            training_count=len(examples),
        )
        BoundedRuleSandbox.validate(program)
        return program

def digest(self) -> str:
        payload = {
            "program_id": self.program_id,
            "target_capability": self.target_capability,
            "target_organ": self.target_organ,
            "rules": [
                {
                    "predicates": [asdict(p) for p in rule.predicates],
                    "output": rule.output,
                    "support": rule.support,
                    "confidence": rule.confidence,
                }
                for rule in self.rules
            ],
            "default_output": self.default_output,
            "source_digest": self.source_digest,
            "training_count": self.training_count,
        }
        return hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()

class SequencePlannerSynthesizer:
    """Learn an ordered action policy from examples using stable action prerequisites."""

    @staticmethod
    def _feature_candidates(payload: Mapping[str, Any]) -> List[RulePredicate]:
        features: List[RulePredicate] = []
        for field, value in payload.items():
            if isinstance(value, (str, int, float, bool)) or value is None:
                features.append(RulePredicate("EQ", str(field), value))
            if isinstance(value, str) and len(value) <= BoundedRuleSandbox.MAX_TEXT_LENGTH:
                for token in sorted(set(re.findall(r"[^\W_]+", value.lower(), flags=re.UNICODE))):
                    if len(token) >= 2:
                        features.append(RulePredicate("TEXT_HAS_TOKEN", str(field), token))
        return features

    @classmethod
    def synthesize(
        cls,
        target_capability: str,
        target_organ: str,
        examples: Sequence[Mapping[str, Any]],
        min_support: int = 2,
    ) -> SequencePlannerProgram:
        if len(examples) < 4:
            raise ValueError("sequence planner requires at least 4 examples")
        if min_support < 2:
            raise ValueError("min_support must be >= 2")

        normalized: List[Tuple[Mapping[str, Any], List[str]]] = []
        for example in examples:
            inp = example.get("input")
            expected = example.get("expected")
            if not isinstance(inp, Mapping) or not isinstance(expected, list) or not all(isinstance(x, str) for x in expected):
                raise ValueError("planner requires mapping input and list[str] expected")
            if len(expected) != len(set(expected)):
                raise ValueError("planner example contains duplicate actions")
            normalized.append((inp, expected))

        all_actions = sorted(set(itertools.chain.from_iterable(plan for _, plan in normalized)))
        if not all_actions:
            raise ValueError("plans must contain actions")

        rules: List[PlannerRule] = []
        for action in all_actions:
            positives = [i for i, (_, plan) in enumerate(normalized) if action in plan]
            negatives = [i for i, (_, plan) in enumerate(normalized) if action not in plan]
            if len(positives) == len(normalized):
                predicate = None
                support = len(positives)
            else:
                if len(positives) < min_support:
                    raise ValueError(f"action lacks support: {action}")
                # Candidate must cover every positive case and no negative case.
                candidate_map: Dict[str, RulePredicate] = {}
                for idx in positives:
                    for feature in cls._feature_candidates(normalized[idx][0]):
                        candidate_map[canonical_json(asdict(feature))] = feature
                valid: List[RulePredicate] = []
                for feature in candidate_map.values():
                    pos_match = all(BoundedRuleSandbox._match(feature, normalized[i][0]) for i in positives)
                    neg_match = any(BoundedRuleSandbox._match(feature, normalized[i][0]) for i in negatives)
                    if pos_match and not neg_match:
                        valid.append(feature)
                if not valid:
                    raise ValueError(f"no stable prerequisite for action: {action}")
                valid.sort(key=lambda p: (0 if p.op == "EQ" else 1, p.field, canonical_json(p.value)))
                predicate = valid[0]
                support = len(positives)

            order_values = [plan.index(action) for _, plan in normalized if action in plan]
            rules.append(
                PlannerRule(
                    action=action,
                    order=sum(order_values) / len(order_values),
                    predicate=predicate,
                    support=support,
                    confidence=1.0,
                )
            )

        # Reject training corpora with inconsistent relative action ordering.
        learned_order = [r.action for r in sorted(rules, key=lambda r: (r.order, r.action))]
        position = {action: i for i, action in enumerate(learned_order)}
        for _, plan in normalized:
            if plan != sorted(plan, key=lambda action: position[action]):
                raise ValueError("inconsistent action ordering cannot be represented by bounded planner")

        program = SequencePlannerProgram(
            program_id=f"PL-{uuid.uuid4().hex[:12]}",
            target_capability=target_capability,
            target_organ=target_organ,
            rules=rules,
            source_digest=hashlib.sha256(canonical_json(list(examples)).encode("utf-8")).hexdigest(),
            training_count=len(examples),
        )
        SequencePlannerSandbox.validate(program)
        return program

